      parent_bytes < 2 || parent_bytes > AUX_EXEC_DENIED_PATH_CAPACITY ||
      roots->denied.paths[0][0] != '/' ||
      roots->denied.paths[0][parent_bytes - 1] != '\0' ||
      std::memchr(roots->denied.paths[0], '\0', parent_bytes - 1)) return {};
