      node::GetCurrentEnvironment(isolate->GetCurrentContext()) == worker.environment &&
      node::GetCurrentEventLoop(isolate) == worker.loop;
}
struct Observation {
  napi_env expected;
  node::Environment* environment;
  v8::Isolate* isolate;
  pthread_t thread;
  bool matched = false;
