                                      bytes_including_nul) == 0 &&
      *bytes_including_nul > 1 && *bytes_including_nul <= capacity &&
      output[*bytes_including_nul - 1] == '\0' &&
      AuxNativeContextValidateCurrentAuthority(pending.owner->handle) == 0 &&
